"use strict";
const pages = {overview:"Tổng quan",progression:"Tiến trình & nhịp chơi",economy:"Cân bằng & roster",cadence:"Nhịp thế giới",config:"Config explorer",changes:"Ba commit gần nhất"};
const colors={COMMON:"#84e1a4",RARE:"#6bcdf2",EPIC:"#c49cf8",LEGENDARY:"#ffd16f",MYTHIC:"#ff8585",APEX:"#ff9c62",LIMITED:"#c8d66d"};
const s={data:null,page:"overview",petSearch:"",rarity:"all",sort:"Price",configFile:"",configSearch:"",offset:0,metric:"NextLevelMoney",day:1};
const root=document.getElementById("content");
const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const t=name=>s.data.tables.find(x=>x.path.endsWith("/"+name))||{rows:[],headers:[],path:""};
const n=v=>{const x=Number(String(v??"").replace(/,/g,""));return Number.isFinite(x)?x:0};
const big=v=>{const x=String(v??"").trim();if(!/^\d+$/.test(x))return x||"—";if(x.length<5)return Number(x).toLocaleString("en-US");const g=Math.floor((x.length-1)/3),e=g*3,suf=["","k","m","B","T","Q","i_Qi","Sx","Sp","Oc","No","De"][g];return suf===undefined?x[0]+"."+x.slice(1,3)+"e"+e:x.slice(0,x.length-e)+(x.slice(x.length-e,x.length-e+2).replace(/0+$/,"")? "."+x.slice(x.length-e,x.length-e+2).replace(/0+$/,""):"")+suf};
const pill=(txt,tone)=>'<span class="tag '+(tone||"")+'">'+esc(txt)+"</span>";
const kpi=(a,b,c)=>'<article class="kpi"><div class="kpi-label">'+esc(a)+'</div><div class="kpi-value kpi-accent">'+esc(b)+'</div><div class="kpi-sub">'+esc(c)+"</div></article>";
const head=(ey,title,lead,tags)=>'<div class="page-head"><div><p class="eyebrow">'+esc(ey)+'</p><h1>'+esc(title)+'</h1><p class="lead">'+esc(lead)+'</p></div><div class="page-actions">'+(tags||"")+"</div></div>";
const panel=(title,sub,body)=>'<section class="panel"><div class="panel-head"><div><h2 class="panel-title">'+esc(title)+'</h2><p class="panel-sub">'+esc(sub||"")+"</p></div></div>"+body+"</section>";
const note=(title,detail,src,tone)=>'<div class="callout '+(tone||"review")+'"><div class="callout-title">'+esc(title)+'</div><p>'+esc(detail)+'</p>'+(src?'<span class="source-ref">'+esc(src)+"</span>":"")+"</div>";
const rarity=r=>'<span class="rarity rarity-'+esc(r)+'">'+esc(r)+"</span>";
const pretty=v=>String(v||"").toLowerCase().replace(/_/g," ").replace(/\b\w/g,x=>x.toUpperCase());
function findings(){return (s.data.findings||[]).map(f=>note(f.title,f.detail,f.kind==="config_coverage"?"PetConfigs.fcg · Pet.csv":f.kind==="annotation_drift"?"PetParadeManager.fcg · HudDebug.fcg":"RebirthConfigs.fcg · rebirth.csv · 40-rebirth-rewards.md")).join("")}
function bars(o){const max=Math.max(1,...Object.values(o));return '<div class="bar-list">'+Object.keys(o).filter(k=>k!=="blank"&&o[k]>0).sort((a,b)=>Object.keys(colors).indexOf(a)-Object.keys(colors).indexOf(b)).map(k=>'<div class="bar-row"><span class="bar-name">'+(colors[k]?rarity(k):esc(k))+'</span><div class="bar-track"><div class="bar-fill" style="width:'+Math.max(3,o[k]/max*100)+'%;--bar-color:'+(colors[k]||"#82e0ba")+'"></div></div><span class="bar-count">'+o[k]+"</span></div>").join("")+"</div>"}
function pillars(){const a=[["01","Base còn phơi lộ","Thu nhập thụ động tạo lý do quay lại; ra ngoài hoạt động có rủi ro cho base."],["02","Trộm có mất mát thật","Phòng thủ và phục hồi là lựa chọn có giá; không xoá hậu quả trộm pet."],["03","Rarity là trục chính","Mutation và Weather bổ sung cách đọc pet, không làm phẳng rarity."],["04","Công bằng với trẻ nhỏ","Không premium-only recovery hoặc kênh chuyển tiền trực tiếp giữa người chơi."],["05","Đọc state hiện có","Ưu tiên rarity, level, mutation, weather và look trước khi thêm state mới."]];return '<div class="pillar-grid">'+a.map(x=>'<article class="pillar"><span class="pillar-num">'+x[0]+'</span><h3>'+esc(x[1])+'</h3><p>'+esc(x[2])+"</p></article>").join("")+"</div>"}
function updateMeta(){document.getElementById("branch-pill").textContent=s.data.sourceBranch||"local";document.getElementById("source-short").textContent=String(s.data.sourceCommit||"").slice(0,8);document.getElementById("crumb-current").textContent=pages[s.page];document.getElementById("footer-source").textContent="Snapshot "+String(s.data.sourceCommit||"").slice(0,8)+" · CSV/config trong checkout · không phải proposal"}
function chart(rows,key,log){if(!rows.length)return'<div class="empty">Chưa có dữ liệu.</div>';const W=720,H=220,L=50,R=18,T=16,B=30;let vs=rows.map(r=>n(r[key]));if(log)vs=vs.map(v=>v>0?Math.log10(v):0);let mn=Math.min(...vs),mx=Math.max(...vs);if(mn===mx){mn-=1;mx+=1}const x=i=>L+i*(W-L-R)/Math.max(1,rows.length-1),y=v=>T+(mx-v)*(H-T-B)/(mx-mn),pts=rows.map((r,i)=>[x(i),y(vs[i]),r]);const path=pts.map((p,i)=>(i?"L":"M")+p[0].toFixed(1)+" "+p[1].toFixed(1)).join(" ");let grid="";for(let i=0;i<=4;i++){let gy=T+i*(H-T-B)/4,gv=mx-i*(mx-mn)/4;grid+='<line class="chart-grid" x1="'+L+'" y1="'+gy+'" x2="'+(W-R)+'" y2="'+gy+'"></line><text class="chart-label" x="4" y="'+(gy+3)+'">'+(log?"10^"+gv.toFixed(0):gv.toFixed(1))+"</text>"}const marks=pts.map(p=>'<circle class="chart-point" cx="'+p[0].toFixed(1)+'" cy="'+p[1].toFixed(1)+'" r="3"><title>RB '+esc(p[2].ID)+" · "+esc(big(p[2][key]))+"</title></circle>").join("");const ids=[0,Math.floor((rows.length-1)/2),rows.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(i=>'<text class="chart-label" text-anchor="middle" x="'+x(i)+'" y="'+(H-7)+'">RB '+esc(rows[i].ID)+"</text>").join("");return'<div class="chart-wrap"><svg class="chart-svg" viewBox="0 0 '+W+" "+H+'" role="img" aria-label="'+esc(key)+'">'+grid+'<path class="chart-area" d="'+path+" L "+pts.at(-1)[0]+" "+(H-B)+" L "+pts[0][0]+" "+(H-B)+" Z"+'"></path><path class="chart-line" d="'+path+'"></path>'+marks+ids+"</svg></div>"}
function overview(){const f=s.data.codeFacts,r=t("rebirth.csv").rows,counts=f.petCsvRarityRows;return head("DESIGN SNAPSHOT","Steal A Pet · GDD cân bằng","Một góc nhìn source-linked về roster, Rebirth gates, kinh tế pet và nhịp world event trong checkout hiện tại.",pill("Live config snapshot","mint")+pill("Không phải proposal"))+
'<section class="hero"><div class="hero-inner"><div><p class="eyebrow">CORE LOOP</p><h2>Sưu tầm pet. Xây thu nhập. Quyết định lúc nào rời base.</h2><p>Pet tạo thu nhập thụ động trong base; roster, mutation, weather và Rebirth mở rộng lựa chọn; ra ngoài săn hoặc trộm pet đưa người chơi vào vùng rủi ro.</p><div class="hero-badges">'+pill("Rarity dẫn dắt collection","mint")+pill("Rebirth là progression spine")+pill("Base exposure giữ lựa chọn có giá","amber")+'</div></div><div class="hero-side"><strong>Giới hạn đọc dữ liệu</strong>Cadence bên dưới lấy từ code/config. Chưa có simulator đã hiệu chỉnh, cohort minutes-to-goal hay retention export để kết luận thời lượng chơi thực tế.</div></div></section>'+
'<section class="kpi-grid">'+kpi("PET SPAWN ROSTER",f.petCount+" IDs","PetConfigs loop 1–"+f.petCount)+kpi("REBIRTH ROWS",r.length,"Runtime count lấy từ CSV")+kpi("WEATHER LOOP",f.weatherDurationUnitVerifiedByCode?f.weatherCycleMinutesFromTable+" phút":"unit cần rà",t("weatherWaves.csv").rows.length+" wave rows")+kpi("CONFIG TABLES",s.data.currentSourceFiles,"CSV trong allowlist")+ "</section>"+
'<section class="section-grid">'+panel("Pet.csv · rarity","Số record theo bảng; không phải xác suất spawn",bars(counts)+'<div class="table-foot"><span>'+t("Pet.csv").rows.length+" CSV rows</span><span>"+(f.petRowsOutsideRuntimeRanges||[]).length+" ngoài loader ranges</span></div>")+panel("Điểm cần đối chiếu","Khác biệt giữa ghi chú, bảng và runtime code",findings()||'<div class="inline-note">Chưa thấy review flags.</div>')+"</section>"+
'<section class="section-grid equal">'+panel("Design rails","Rulings SAP giữ làm baseline",pillars())+panel("Progression hiện có","Giá trị đọc từ rebirth.csv",'<div class="split-stat"><div><strong>RB 1 → RB '+esc(r.at(-1)?.ID||"—")+'</strong><span>rows hiện có</span></div><div><strong>'+esc(r[0]?.MoneyMultiplier||"—")+'× → '+esc(r.at(-1)?.MoneyMultiplier||"—")+'×</strong><span>MoneyMultiplier</span></div><div><strong>'+esc(r[0]?.MobAmount||"—")+' → '+esc(r.at(-1)?.MobAmount||"—")+'</strong><span>MobAmount</span></div></div>'+note("Pacing theo gate, chưa theo phút","RB0→RB1 được SAP reference gọi là tutorial/retention cliff. Thời gian đạt gate cần simulator và telemetry; site hiện chỉ thể hiện cost, pet requirement, slots và unlock.","systems_reference.md · 40-rebirth-rewards.md","info"))+"</section>"+
'<div class="inline-note">Snapshot '+esc(new Date(s.data.generatedAt).toLocaleString("vi-VN"))+" · branch "+esc(s.data.sourceBranch)+" · commit "+esc(String(s.data.sourceCommit).slice(0,12))+".</div>"}
function unlockHtml(){const g=new Map();(s.data.codeFacts.featureUnlocks||[]).forEach(x=>g.set(x.rebirth,(g.get(x.rebirth)||[]).concat(x.features)));return[...g.entries()].sort((a,b)=>a[0]-b[0]).map(([rb,fs])=>'<div class="unlock-row"><span class="unlock-level">RB '+rb+'</span><div class="unlock-line">'+fs.map(f=>'<span class="unlock-chip">'+esc(pretty(f))+"</span>").join("")+'</div><span class="unlock-count">'+fs.length+" gate</span></div>").join("")}
function petNameList(raw){const m=new Map(t("Pet.csv").rows.map(r=>[r.ID,r.Name]));return String(raw||"").split(",").map(x=>x.trim()).filter(Boolean).map(x=>(m.get(x)?m.get(x)+" · ":"")+x).join(", ")}
function progression(){const r=t("rebirth.csv").rows,log=s.metric==="NextLevelMoney";return head("PROGRESSION","Rebirth mở dần roster và hệ thống","Đọc gate hiện tại: tiền, pet yêu cầu, số tầng, slot và feature unlock. Không đổi cash thành thời gian khi chưa có income model.",pill("Source · rebirth.csv")+pill("Session minutes chưa mô phỏng","amber"))+
'<section class="kpi-grid">'+kpi("REBIRTH ROWS",r.length,"Loader đếm row dữ liệu")+kpi("MONEY MULTIPLIER",(r.at(-1)?.MoneyMultiplier||"—")+"×","row cuối trong checkout")+kpi("PET SLOTS",(r[0]?.MobAmount||"—")+" → "+(r.at(-1)?.MobAmount||"—"),"MobAmount")+kpi("FLOORS",(r[0]?.FloorsCount||"—")+" → "+(r.at(-1)?.FloorsCount||"—"),"FloorsCount")+"</section>"+
'<section class="section-grid">'+panel("Cost curve",log?"NextLevelMoney · log scale":"MoneyMultiplier · linear",'<div class="filterbar"><label class="small-count" for="rb-metric">Hiển thị</label><select id="rb-metric" class="field-select"><option value="NextLevelMoney"'+(log?" selected":"")+'>NextLevelMoney · log</option><option value="MoneyMultiplier"'+(!log?" selected":"")+'>MoneyMultiplier</option></select></div>'+chart(r,s.metric,log))+panel("Feature gates","Ngưỡng được trích từ FeatureUnlockConfigs",'<div class="unlock-track">'+unlockHtml()+'</div><div class="table-foot"><span>'+s.data.codeFacts.featureUnlocks.length+" nhánh return level</span><span>Không phải phút chơi</span></div>")+"</section>"+
'<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Rebirth table</h2><p class="panel-sub">Giá trị tiền giữ nguyên chuỗi số nguồn; NextLevelMobList được map sang pet name khi có ID phù hợp.</p></div></div><div class="table-wrap"><table><thead><tr><th>Level</th><th class="num">Multiplier</th><th class="num">Floors</th><th class="num">Mob slots</th><th class="num">Next cash</th><th>Next pets</th></tr></thead><tbody>'+r.map(x=>'<tr><td class="mono">RB '+esc(x.ID)+'</td><td class="num">'+esc(x.MoneyMultiplier)+'×</td><td class="num">'+esc(x.FloorsCount)+'</td><td class="num">'+esc(x.MobAmount)+'</td><td class="num">'+esc(big(x.NextLevelMoney))+'</td><td>'+esc(petNameList(x.NextLevelMobList))+"</td></tr>").join("")+"</tbody></table></div></section>"+findings()}
function filteredPets(){return t("Pet.csv").rows.filter(r=>(s.rarity==="all"||r.Rarity===s.rarity)&&(!s.petSearch||[r.ID,r.Name,r.Rarity,r.Rank].join(" ").toLowerCase().includes(s.petSearch.toLowerCase()))).sort((a,b)=>s.sort==="Name"?a.Name.localeCompare(b.Name):(BigInt(a[s.sort]||0)>BigInt(b[s.sort]||0)?-1:1))}
function petRows(rows){return rows.slice(0,100).map(r=>'<tr data-pet="'+esc(r.ID)+'" tabindex="0" role="button"><td class="mono">'+esc(r.ID)+'</td><td><strong>'+esc(r.Name)+'</strong></td><td>'+rarity(r.Rarity)+'</td><td class="num">'+esc(big(r.Value))+'</td><td class="num">'+esc(big(r.Price))+'</td><td class="num">'+(n(r.Value)&&n(r.Price)?(n(r.Value)/n(r.Price)).toFixed(3)+"×":"—")+"</td></tr>").join("")}
function updatePetRows(){const rows=filteredPets(),body=document.getElementById("pet-rows");if(!body)return;body.innerHTML=petRows(rows)||'<tr><td colspan="6" class="empty">Không có pet khớp bộ lọc.</td></tr>';document.getElementById("pet-count").textContent=Math.min(rows.length,100)+" / "+rows.length+" dòng"}
function economy(){const rows=t("Pet.csv").rows,ms=t("mutation.csv").rows,counts=s.data.codeFacts.petCsvRarityRows;const high=rows.filter(r=>n(r.Value)>0).sort((a,b)=>n(b.Value)-n(a.Value)).slice(0,6);return head("ECONOMY & ROSTER","Rarity dẫn trục; modifier mở lớp lựa chọn","So sánh giá, income, rarity và mutation multiplier từ config. Số tiền lớn được giữ dạng chuỗi trong bảng nguồn.",pill("Pet.csv + mutation.csv"))+
'<section class="kpi-grid">'+kpi("PET CSV ROWS",rows.length,"Có record event/đặc biệt")+kpi("NORMAL PET LOOP",s.data.codeFacts.petCount,"PET_COUNT trong PetConfigs")+kpi("MUTATION ROWS",ms.length,"Tier và multiplier")+kpi("LOADER OUTLIERS",(s.data.codeFacts.petRowsOutsideRuntimeRanges||[]).length,"CSV rows ngoài load ranges")+"</section>"+
'<section class="section-grid">'+panel("Rarity distribution","CSV rows theo rarity · không phải spawn odds",bars(counts))+panel("Mutation multiplier","Theo Tier trong mutation.csv",'<div class="mutation-ladder">'+ms.slice().sort((a,b)=>n(a.Tier)-n(b.Tier)).map(r=>'<div class="mutation-row"><span class="mutation-tier">T'+esc(r.Tier)+'</span><span class="mutation-name">'+esc(r.Name)+'</span><div class="mutation-track"><span style="width:'+Math.max(3,n(r.Multiplier)/2.5*100)+'%"></span></div><span class="mutation-value">'+esc(r.Multiplier)+"×</span></div>").join("")+"</div>")+"</section>"+
'<section class="section-grid"><div class="panel"><div class="panel-head"><div><h2 class="panel-title">Pet roster</h2><p class="panel-sub">Click row để xem đầy đủ config</p></div></div><div class="filterbar"><div class="search-wrap"><input id="pet-search" value="'+esc(s.petSearch)+'" placeholder="Tìm tên, ID, rarity…" aria-label="Tìm pet"></div><select id="pet-rarity"><option value="all">Tất cả rarity</option>'+Object.keys(colors).filter(x=>counts[x]).map(x=>'<option value="'+x+'"'+(s.rarity===x?" selected":"")+'>'+x+"</option>").join("")+'</select><select id="pet-sort"><option value="Price">Giá cao → thấp</option><option value="Value"'+(s.sort==="Value"?" selected":"")+'>Value cao → thấp</option><option value="Name"'+(s.sort==="Name"?" selected":"")+'>Tên A → Z</option></select></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Pet</th><th>Rarity</th><th class="num">Value</th><th class="num">Price</th><th class="num">Value / Price</th></tr></thead><tbody id="pet-rows">'+petRows(filteredPets())+"</tbody></table></div><div class=\"table-foot\"><span id=\"pet-count\">"+Math.min(filteredPets().length,100)+" / "+filteredPets().length+" dòng</span><span>CSV values · not spawn chance</span></div></div>"+
panel("High value rows","Danh sách review, không phải power ranking",'<div class="timeline">'+high.map(r=>'<div class="timeline-row"><span class="timeline-key">#'+esc(r.ID)+'</span><div class="timeline-detail"><strong>'+esc(r.Name)+'</strong> '+rarity(r.Rarity)+'<small>Value '+esc(big(r.Value))+' · Price '+esc(big(r.Price))+"</small></div></div>").join("")+"</div>")+"</section>"+
((s.data.codeFacts.petRowsOutsideRuntimeRanges||[]).length?note("Pet.csv row ngoài loader ranges","GAUR (120) và TAPIR (1047) được giữ trong explorer nhưng không nằm trong các loop đọc ID mà PetConfigs khai báo.","PetConfigs.fcg · Pet.csv"):"")}
function weatherList(){const w=new Map(t("weather.csv").rows.map(r=>[r.ID,r.Name])),rows=t("weatherWaves.csv").rows,total=rows.reduce((a,r)=>a+n(r.Duration),0);return'<div class="timeline">'+rows.map((r,i)=>'<div class="timeline-row"><span class="timeline-key">Wave '+esc(r.ID)+'</span><div class="timeline-detail"><strong>'+esc(w.get(r.WeatherType)||(r.WeatherType==="0"?"Clear / none":"Type "+r.WeatherType))+'</strong> · '+esc(r.Duration)+' phút<small><span class="bar-track" style="display:block;height:5px;margin-top:6px"><span class="bar-fill" style="display:block;width:'+n(r.Duration)/Math.max(1,total)*100+'%;--bar-color:'+(i%3===0?"#82e0ba":i%3===1?"#73d2e8":"#b49cff")+'"></span></span></small></div></div>').join("")+"</div>"}
function cadence(){const f=s.data.codeFacts,field="Day "+s.day,rows=t("Pet.csv").rows.filter(r=>Number(r.ID)<=f.petCount&&r[field]),counts={UP:0,NORMAL:0,DOWN:0};rows.forEach(r=>counts[r[field]]=(counts[r[field]]||0)+1);const opts=Array.from({length:7},(_,i)=>i+1).map(d=>'<option value="'+d+'"'+(s.day===d?" selected":"")+'>Day '+d+"</option>").join("");const missions=t("DailyMissions.csv").rows.filter(r=>r.Day==="0"),dust=t("DustHuntWave.csv").rows;return head("CADENCE","Cadence cấu hình, không phải session target","Một nhịp đọc từ source: pet parade, weather waves và daily activity. Đây là cấu hình world; không đại diện thời gian người chơi thực tế.",pill("Weather unit đã đối chiếu","mint")+pill("Dust Hunt unit cần review","amber"))+
'<section class="kpi-grid">'+kpi("PET SPAWN INTERVAL",f.spawnIntervalMs/1000+" giây","GlobalConfigs.PetSpawnInterval")+kpi("PARADE WAVE POOL",f.paradePetsPerWave+" pets","PETS_COUNT_PER_WAVE")+kpi("WEATHER ROTATION",f.weatherCycleMinutesFromTable+" phút",t("weatherWaves.csv").rows.length+" wave rows")+kpi("WEEKEND WEIGHT",f.weekendSpawnMultiplier+"×","Rarity cao ở Type3–Type5")+"</section>"+
'<section class="section-grid">'+panel("Weather timeline","Duration trong weatherWaves.csv là phút; code nhân 60 để lấy seconds",weatherList())+panel("Daily pool modifier","UP/NORMAL/DOWN nhân parade weight theo cycle day",'<div class="filterbar"><label class="small-count">Cycle</label><select id="day-select" class="field-select">'+opts+'</select>'+pill("UP × "+f.dailyModifiers.up)+pill("NORMAL × "+f.dailyModifiers.normal)+pill("DOWN × "+f.dailyModifiers.down)+'</div>'+bars(counts)+'<div class="table-foot"><span>'+rows.length+" normal IDs có state</span><span>Day "+s.day+"</span></div>")+"</section>"+
'<section class="section-grid equal">'+panel("Daily mission pool",missions.length+" Day 0 rows · "+new Set(missions.map(r=>r.Action)).size+" actions",'<div class="pill-list">'+[...new Set(missions.map(r=>r.Action))].map(x=>'<span class="soft-pill">'+esc(x)+"</span>").join("")+"</div>")+panel("Dust Hunt raw phases","Không gắn phút/giây tới khi đối chiếu runtime",'<div class="timeline">'+dust.map(r=>'<div class="timeline-row"><span class="timeline-key">IsAppear '+esc(r.IsAppear)+'</span><div class="timeline-detail"><strong>Duration '+esc(r.Duration)+'</strong><small>Raw value từ DustHuntWave.csv</small></div></div>').join("")+"</div>"+note("Getter trả raw value","GetDustHuntWaveDurationSeconds có tên seconds nhưng trả nguyên duration; WeatherConfigs có phép nhân 60 rõ ràng. Xác minh trước khi đổi sang cadence phút/giây.","DustHuntConfigs.fcg · DustHuntWave.csv"))+"</section>"+findings()}

